async function showBreakEven(){
  breakEvenOpen=true;breakEvenLoad={status:'loading',errors:{}};render();
  if(App.mode!=='shared')return;
  const [teaching,integrated]=await Promise.allSettled([api('teaching-load/costs'),api(`break-even/integrated?year=${encodeURIComponent(breakEvenYear)}`)]);
  if(!breakEvenOpen)return;
  teachingCostPreview=teaching.status==='fulfilled'?teaching.value:null;
  breakEvenIntegrated=integrated.status==='fulfilled'?integrated.value:null;
  const errors={};
  const failure=(reason,endpoint)=>({endpoint:reason?.endpoint||endpoint,httpStatus:reason?.httpStatus||null,message:String(reason?.responseBody?.error||reason?.message||'Falha ao carregar endpoint')});
  if(teaching.status==='rejected')errors.teaching=failure(teaching.reason,'/api/teaching-load/costs');
  if(integrated.status==='rejected')errors.integrated=failure(integrated.reason,'/api/break-even/integrated?year=2027');
  breakEvenLoad={status:Object.keys(errors).length?(teachingCostPreview||breakEvenIntegrated?'partial':'error'):'loaded',errors};
  render();
  if(Object.keys(errors).length)toast('PE carregado parcialmente: '+Object.values(errors).map(item=>item.message).join(' · '));
}
